func TestAWSBedrock_RequestBody_Path(t *testing.T) {
	t.Run("non-streaming uses converse path", func(t *testing.T) {
		raw, _ := json.Marshal(openai.ChatCompletionRequest{Model: "anthropic.claude-3-5-sonnet-20241022-v2:0", Stream: false})
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{})
		headers, _, err := o.RequestBody(raw)
		require.NoError(t, err)
		var pathHdr string
		for _, h := range headers {
			if h.Name == pathHeaderName {
				pathHdr = h.Value
			}
		}
		require.Contains(t, pathHdr, "/converse")
		require.NotContains(t, pathHdr, "converse-stream")
	})

	t.Run("streaming uses converse-stream path", func(t *testing.T) {
		raw, _ := json.Marshal(openai.ChatCompletionRequest{Model: "anthropic.claude-3-5-sonnet-20241022-v2:0", Stream: true})
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{})
		headers, _, err := o.RequestBody(raw)
		require.NoError(t, err)
		var pathHdr string
		for _, h := range headers {
			if h.Name == pathHeaderName {
				pathHdr = h.Value
			}
		}
		require.Contains(t, pathHdr, "converse-stream")
	})

	t.Run("model name override applied to path", func(t *testing.T) {
		override := "anthropic.claude-3-haiku-20240307-v1:0"
		raw, _ := json.Marshal(openai.ChatCompletionRequest{Model: "my-model", Stream: false})
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{BackendModel: override})
		headers, _, err := o.RequestBody(raw)
		require.NoError(t, err)
		var pathHdr string
		for _, h := range headers {
			if h.Name == pathHeaderName {
				pathHdr = h.Value
			}
		}
		require.Contains(t, pathHdr, url.PathEscape(override))
	})

	t.Run("ARN model slash is path-escaped", func(t *testing.T) {
		arnModel := "arn:aws:bedrock:us-east-1::foundation-model/anthropic.claude-3-5-sonnet-20241022-v2:0"
		raw, _ := json.Marshal(openai.ChatCompletionRequest{Model: arnModel, Stream: false})
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{})
		headers, _, err := o.RequestBody(raw)
		require.NoError(t, err)
		var pathHdr string
		for _, h := range headers {
			if h.Name == pathHeaderName {
				pathHdr = h.Value
			}
		}
		require.Contains(t, pathHdr, "%2F", "slash in ARN must be path-escaped")
	})
}

func TestAWSBedrock_RequestBody_Messages(t *testing.T) {
	t.Run("user message converted", func(t *testing.T) {
		raw, _ := json.Marshal(openai.ChatCompletionRequest{
			Model: "anthropic.claude-3-5-sonnet-20241022-v2:0",
			Messages: []openai.ChatCompletionMessageParamUnion{
				{OfUser: &openai.ChatCompletionUserMessageParam{
					Role:    openai.ChatMessageRoleUser,
					Content: openai.StringOrUserRoleContentUnion{Value: "hello"},
				}},
			},
		})
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{})
		_, body, err := o.RequestBody(raw)
		require.NoError(t, err)
		require.NotNil(t, body)
		var req awsbedrock.ConverseInput
		require.NoError(t, json.Unmarshal(body, &req))
		require.Len(t, req.Messages, 1)
		require.Equal(t, "user", req.Messages[0].Role)
	})
}

func TestAWSBedrock_ResponseHeaders(t *testing.T) {
	t.Run("streaming eventstream content-type rewritten", func(t *testing.T) {
		raw, _ := json.Marshal(openai.ChatCompletionRequest{Model: "m", Stream: true})
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{})
		_, _, err := o.RequestBody(raw)
		require.NoError(t, err)
		headers, err := o.ResponseHeaders(map[string]string{
			"content-type":    "application/vnd.amazon.eventstream",
			"x-amzn-requestid": "test-req-id",
		})
		require.NoError(t, err)
		require.NotEmpty(t, headers)
		require.Equal(t, contentTypeHeaderName, headers[0].Name)
		require.Equal(t, "text/event-stream", headers[0].Value)
	})

	t.Run("non-streaming returns no headers", func(t *testing.T) {
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{})
		headers, err := o.ResponseHeaders(map[string]string{"content-type": "application/json"})
		require.NoError(t, err)
		require.Empty(t, headers)
	})
}

func TestAWSBedrock_ResponseBody_NonStreaming(t *testing.T) {
	t.Run("valid bedrock response converted to openai", func(t *testing.T) {
		respBody := awsbedrock.ConverseResponse{
			Output: &awsbedrock.ConverseOutput{
				Message: awsbedrock.Message{
					Role: "assistant",
					Content: []*awsbedrock.ContentBlock{
						{Text: strPtr("Hello from Bedrock")},
					},
				},
			},
			StopReason: strPtr("end_turn"),
			Usage: &awsbedrock.TokenUsage{
				InputTokens:  10,
				OutputTokens: 5,
				TotalTokens:  15,
			},
		}
		raw, _ := json.Marshal(respBody)
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{})
		_, _, err := o.RequestBody([]byte(`{"model":"m"}`))
		require.NoError(t, err)
		_, body, err := o.ResponseBody(raw, true)
		require.NoError(t, err)
		var openAIResp openai.ChatCompletionResponse
		require.NoError(t, json.Unmarshal(body, &openAIResp))
		require.Len(t, openAIResp.Choices, 1)
		require.NotNil(t, openAIResp.Choices[0].Message.Content)
		require.Equal(t, "Hello from Bedrock", *openAIResp.Choices[0].Message.Content)
		require.Equal(t, 10, openAIResp.Usage.PromptTokens)
		require.Equal(t, 5, openAIResp.Usage.CompletionTokens)
		require.Equal(t, 15, openAIResp.Usage.TotalTokens)
	})

	t.Run("missing output returns error", func(t *testing.T) {
		respBody := awsbedrock.ConverseResponse{StopReason: strPtr("error")}
		raw, _ := json.Marshal(respBody)
		o := NewChatCompletionOpenAIToAWSBedrockTranslator(ProviderConfig{})
		_, _, err := o.ResponseBody(raw, true)
		require.Error(t, err)
	})
}

